function Icon({ name, size = 22 }: { name: string; size?: number }) {

  return <img src={`${ICONS}${name}`} width={size} height={size} alt="" aria-hidden="true" />;

}

type MatchTerm = { id: string; label: string };

type MatchOption = { id: string; text: string };

type HotspotArea = {
  id: string; label: string; x: number; y: number; width: number; height: number;
  correct: boolean;
};
type HotspotQuestionData = { imageSrc: string; maxMarkers: number; areas: HotspotArea[] };
type PlacedMarker = { id: string; x: number; y: number; areaId?: string; label: string };

type MatchQuestion = {
  hotspot?: HotspotQuestionData;

  id: string;

  text: string;

  terms: MatchTerm[];

  options: MatchOption[];

  columnA?: string;

  columnB?: string;

  // Expected option index for each term. -1 means no correct answer was supplied.

  correct: number[];

  bloom: string;

  hint: string;

  allowHint: boolean;

  points: number;

};

type ViewerDraft = { title: string; questions: MatchQuestion[]; durationSeconds: number };

type ViewerState = {

  signature: string;

  current: number;

  answers: Record<number, number[]>;
  hotspotAnswers?: Record<number, PlacedMarker[]>;

  flagged: number[];

  skipped: number[];

  expiresAt: number;

  submitted: boolean;

};

