function asData(value: unknown): Data | null {

  return value !== null && typeof value === "object" && !Array.isArray(value)

    ? value as Data : null;

}

function pickText(data: Data, keys: string[], fallback = ""): string {

  for (const key of keys) {

    const value = data[key];

    if (typeof value === "string" && value.trim()) return value.trim();

  }

  return fallback;

}

function numberValue(raw: unknown, fallback: number): number {

  const n = Number(raw);

  return raw !== undefined && raw !== null && raw !== "" && Number.isFinite(n) ? n : fallback;

}

function readStorage(keys: string[]): Data | null {

  for (const key of keys) {

    try {

      const raw = assessmentStorage.getItem(key);

      if (!raw) continue;

      const parsed: unknown = JSON.parse(raw);

      const record = asData(parsed);

      if (record) return record;

      if (Array.isArray(parsed)) return { questions: parsed };

    } catch { /* Another compatible key may exist. */ }

  }

  return null;

}

function toText(raw: unknown): string {

  if (typeof raw === "string" || typeof raw === "number") return String(raw).trim();

  const d = asData(raw);

  return d ? pickText(d, ["text", "label", "name", "term", "description", "title", "value"]) : "";

}

function toOption(raw: unknown, index: number): MatchOption {

  const d = asData(raw);

  return { id: String(d?.id ?? d?.key ?? `option-${index}`), text: toText(raw) };

}

function toTerm(raw: unknown, index: number): MatchTerm {

  const d = asData(raw);

  return { id: String(d?.id ?? d?.key ?? `term-${index}`), label: toText(raw) };

}

function resolveIndex(value: unknown, options: MatchOption[]): number {

  if (typeof value === "number" && Number.isInteger(value)) {

    return value >= 0 && value < options.length ? value : -1;

  }

  if (value === undefined || value === null) return -1;

  const v = String(value).trim();

  if (!v) return -1;

  const byIdOrText = options.findIndex(option =>

    option.id === v || option.text.toLowerCase() === v.toLowerCase());

  if (byIdOrText !== -1) return byIdOrText;

  if (/^\d+$/.test(v)) {

    const n = Number(v);

    return n >= 0 && n < options.length ? n : -1;

  }
  const letter = /^([a-z])\.?$/i.exec(v);

  if (letter) {

    const n = letter[1].toUpperCase().charCodeAt(0) - 65;

    return n < options.length ? n : -1;

  }

  return -1;

}

function imageFromCreator(raw: unknown): string {
  if (raw && typeof raw === "object") {
    const image = asData(raw);
    if (image) {
      // The creator can save a URL, or an actual image data URL.
      // A File object / filename alone cannot be displayed after refresh.
      for (const candidate of [image.dataUrl, image.dataURL, image.base64,
        image.imageSrc, image.imageUrl, image.previewUrl, image.previewSrc,
        image.preview, image.src, image.url, image.path, image.fileData]) {
        const result = imageFromCreator(candidate);
        if (result) return result;
      }
    }
    return "";
  }
  if (typeof raw !== "string") return "";
  const value = raw.trim();
  if (/^data:image\/(?:png|jpe?g|webp|gif|svg\+xml);base64,/i.test(value)) return value;
  if (/^blob:/i.test(value)) return value; // Valid only until the originating page/session releases it.
  if (/^https?:\/\//i.test(value)) return value;
  // Next.js serves files inside public/ from the site root, not from /public/.
  if (/^\/?(?:\.\/)?public\//i.test(value)) return "/" + value.replace(/^\/?(?:\.\/)?public\//i, "");
  if (/^\/(?!\/)/.test(value)) return value;
  if (/^(?:\.\/)?[\w\-. /]+\.(?:png|jpe?g|webp|gif|svg)(?:\?[^\s]*)?$/i.test(value)) {
    return value.startsWith("./") ? "/" + value.slice(2) :
      value.includes("/") ? "/" + value.replace(/^\/+/, "") : "/assets/assessmenticons/" + value;
  }
  return "";
}
function percentage(raw: unknown, fallback: number): number {
  if (raw === null || raw === undefined || raw === "") return fallback;
  const value = parseFloat(String(raw));
  if (!Number.isFinite(value)) return fallback;
  return String(raw).includes("%") ? value : (value >= 0 && value <= 1 ? value * 100 : value);
}
function parseHotspotAreas(q: Data): HotspotArea[] {
  const nested = asData(q.hotspot) ?? {};
  const raw = q.hotspots ?? q.hotspotAreas ?? q.hotspotRegions ?? q.clickAreas ??
    q.clickableAreas ?? q.areas ?? q.regions ?? q.targets ??
    nested.hotspots ?? nested.hotspotAreas ?? nested.areas ?? nested.regions;
  if (!Array.isArray(raw)) return [];
  return raw.map((item, index) => {
    const a = asData(item);
    if (!a) return null;
    const b = asData(a.bounds) ?? asData(a.rect) ?? a;
    const isCorrect = a.correct === true || a.isCorrect === true || a.isAnswer === true ||
      String(a.id ?? "") === String(q.correctAreaId ?? q.correctHotspotId ?? "__none__");
    return {
      id: String(a.id ?? `area-${index}`),
      label: pickText(a, ["label", "name", "text", "answer", "title"], `Area ${index + 1}`),
      x: percentage(b.x ?? b.left, 0),
      y: percentage(b.y ?? b.top, 0),
      width: Math.max(0, percentage(b.width ?? b.w, 0)),
      height: Math.max(0, percentage(b.height ?? b.h, 0)),
      correct: isCorrect,
    };
  }).filter((area): area is HotspotArea => area !== null);
}

function parseQuestion(raw: unknown, index: number): MatchQuestion | null {

  const q = asData(raw);

  if (!q) return null;

  const hotspotInfo = asData(q.hotspot) ?? {};
  const contentInfo = asData(q.content) ?? asData(q.data) ?? {};
  const imageSrc = imageFromCreator(
    q.imageSrc ?? q.imageUrl ?? q.questionImage ?? q.backgroundImage ??
    q.image ?? q.uploadedImage ?? q.imageData ?? q.imagePath ??
    q.pictureSrc ?? q.picture ?? q.backgroundSrc ?? q.uploadedFile ??
    hotspotInfo.imageSrc ?? hotspotInfo.image ?? hotspotInfo.url ??
    contentInfo.imageSrc ?? contentInfo.imageUrl ?? contentInfo.image ?? contentInfo.backgroundImage ??
    contentInfo.uploadedImage ?? contentInfo.imageData ?? contentInfo.questionImage
  );
  const isHotspot = /hotspot|clickable\s+image|image\s+click/i.test(
    String(q.type ?? q.questionType ?? q.assessmentType ?? q.mode ?? q.questionMode ?? "")
  ) || Boolean(imageSrc);
  // Keep the creator's hotspot question even before an image is uploaded.
  // The viewer shows an empty image frame, never a hard-coded CPU image in its place.
  if (isHotspot) {
    const limits = q.maxMarkers ?? q.requiredMarkers ?? q.markerCount ?? q.markers ?? hotspotInfo.maxMarkers;
    return {
      id: String(q.id ?? `question-${index}`),
      text: pickText(q, ["text", "question", "questionText", "instruction", "prompt"], "Click the correct part of the image."),
      terms: [], options: [], correct: [],
      bloom: pickText(q, ["bloom", "bloomTaxonomy", "bloomLevel", "taxonomy"], ""),
      hint: pickText(q, ["hint", "hintText"], ""),
      allowHint: q.allowHint !== false && q.showHint !== false,
      points: Math.max(0, numberValue(q.points ?? q.marks, 1)),
      hotspot: {
        imageSrc,
        maxMarkers: Math.max(1, Math.min(20, Math.floor(numberValue(limits, 1)))),
        areas: parseHotspotAreas(q),
      },
    };
  }
  const text = pickText(q, ["text", "question", "questionText", "instruction", "prompt"], "Match the following.");

  let terms: MatchTerm[] = [];

  let options: MatchOption[] = [];

  let correct: number[] = [];

  // Pair-based authoring: [{ term, description }, ...].

  const pairs = Array.isArray(q.pairs) ? q.pairs : Array.isArray(q.matches) ? q.matches : null;

  if (pairs?.length) {

    terms = pairs.map((pair, i) => {

      const p = asData(pair) ?? {};

      return toTerm({ id: p.id ?? `term-${i}`, text: p.term ?? p.left ?? p.question ?? p.source }, i);

    });

    options = pairs.map((pair, i) => {

      const p = asData(pair) ?? {};

      return toOption({ id: p.optionId ?? `pair-option-${i}`, text: p.description ?? p.right ?? p.answer ?? p.target }, i);

    });

    correct = pairs.map((_, i) => i);

    // Optional distractors: added without changing correct indices.

    const extraChoices = Array.isArray(q.distractors) ? q.distractors

      : Array.isArray(q.extras) && q.extraEnabled !== false ? q.extras

      : [];

    options.push(...extraChoices.map((value, i) => toOption(value, options.length + i)).filter(option => option.text));

  }

  // Terms / descriptions with an explicit mapping.

  if (!terms.length) {

    const left = Array.isArray(q.terms) ? q.terms

      : Array.isArray(q.leftItems) ? q.leftItems

      : Array.isArray(q.questions) ? q.questions : [];

    const right = Array.isArray(q.descriptions) ? q.descriptions

      : Array.isArray(q.rightItems) ? q.rightItems

      : Array.isArray(q.options) ? q.options : [];

    terms = left.map(toTerm).filter(term => term.label);

    options = right.map(toOption).filter(option => option.text);

    const mapping = asData(q.mapping) ?? asData(q.correctMapping) ?? asData(q.answerMapping) ?? {};

    const correctArray = Array.isArray(q.correctAnswers) ? q.correctAnswers

      : Array.isArray(q.correctMapping) ? q.correctMapping : [];

    correct = terms.map((term, i) => resolveIndex(

      correctArray[i] ?? mapping[term.id] ?? mapping[String(i + 1)] ?? mapping[String(i)] ??

      asData(left[i])?.correct ?? asData(left[i])?.answer,

      options,

    ));

  }

  // Compatible with the existing Drag & Drop creator's [[1]] zones, items and mapping.

  if (!terms.length && Array.isArray(q.items) && q.items.length) {
    const found = [...text.matchAll(/\[\[(\d+)\]\]/g)].map(match => match[1]);

    const ids = [...new Set(found)];

    const zoneNames = asData(q.zoneLabels) ?? {};

    terms = ids.map(id => ({ id, label: String(zoneNames[id] ?? `Zone [[${id}]]`) }));

    options = q.items.map(toOption).filter(option => option.text);

    const mapping = asData(q.mapping) ?? {};

    correct = terms.map(term => resolveIndex(mapping[term.id], options));

  }

  if (!terms.length || !options.length) return null;

  // Terms and descriptions are supplied by creator, never altered or hardcoded here.

  return {

    id: String(q.id ?? `question-${index}`), text, terms, options,

    columnA: pickText(q, ["columnA", "leftHeading", "termHeading"], "Term"),

    columnB: pickText(q, ["columnB", "rightHeading", "descriptionHeading"], "Description"),

    correct: terms.map((_, i) => correct[i] ?? -1),

    bloom: pickText(q, ["bloom", "bloomTaxonomy", "bloomLevel", "taxonomy"], ""),

    hint: pickText(q, ["hint", "hintText"], ""),

    allowHint: q.allowHint !== false && q.showHint !== false,

    points: Math.max(0, numberValue(q.points ?? q.marks, 1)),

  };

}

function durationSeconds(detail: Data): number {

  const raw = detail.duration ?? detail.timeLimit ?? detail.totalTime ?? detail.time;

  const minutes = Number.parseFloat(String(raw ?? "60"));

  return Math.round((Number.isFinite(minutes) && minutes > 0 ? minutes : 60) *

    (/hour/i.test(String(raw)) ? 3600 : 60));

}

function loadViewerDraft(): ViewerDraft {
  const query = new URLSearchParams(window.location.search);
  if (query.get("demo") === "hotspot") return HOTSPOT_DEMO;
  if (query.get("demo") === "text") return DEMO;
  const details = readStorage(DETAILS_KEYS) ?? {};
  const id = getActiveAssessmentId();
  const record = id ? getAssessment(id) : undefined;
  // Never read a different assessment type's content; never show demonstration questions to a real learner.
  if (!record || record.typeCode !== "clickable-hotspot") {
    return {title:"Clickable Hotspot",durationSeconds:3600,questions:[]};
  }
  const saved = readStorage(CONTENT_KEYS);
  const nested = asData(saved?.content) ?? asData(saved?.draft) ?? saved ?? {};
  const records = Array.isArray(saved?.questions) ? saved.questions :
    Array.isArray(nested.questions) ? nested.questions : [];
  const questions = records.map(parseQuestion).filter((q):q is MatchQuestion=>
    q !== null && !!q.hotspot?.imageSrc && (q.hotspot.areas.length > 0));
  return {
    title: record.title || pickText(details,["assessmentTitle","assessmentName","title","name"],"Clickable Hotspot"),
    durationSeconds: durationSeconds(details),
    questions,
  };
}

function formatTime(value: number): [string, string, string] {

  const safe = Math.max(0, Math.floor(value));

  return [Math.floor(safe / 3600), Math.floor(safe % 3600 / 60), safe % 60]

    .map(n => String(n).padStart(2, "0")) as [string, string, string];

}

function Stopwatch({ seconds }: { seconds: number }) {

  const parts = formatTime(seconds);

  return <div className="viewerExamClock" role="timer" aria-label={`Time remaining ${parts.join(":")}`}>

    {parts.map((part, i) => <span className="viewerTimeGroup" key={i}>

      {i > 0 && <span className="viewerTimeColon">:</span>}

      {part.split("").map((digit, j) => <span className="viewerTimeDigit" key={j}>{digit}</span>)}

    </span>)}

  </div>;

}

function complete(q: MatchQuestion | undefined, selections: number[] | undefined): boolean {

  if (!q || q.terms.length === 0) return false;

  return q.terms.every((_, index) =>

    Number.isInteger(selections?.[index]) &&

    (selections?.[index] ?? -1) >= 0 &&

    (selections?.[index] ?? -1) < q.options.length);

}

function partial(q: MatchQuestion | undefined, selections: number[] | undefined): boolean {

  return !!q && q.terms.some((_, index) => (selections?.[index] ?? -1) >= 0) && !complete(q, selections);

}

function MatchSelect({ question, termIndex, selected, answers, disabled, onSelect }: {

  question: MatchQuestion;

  termIndex: number;

  selected: number;

  answers: number[];

  disabled: boolean;

  onSelect: (value: number) => void;

}) {

  const [open, setOpen] = useState(false);

  const [position, setPosition] = useState({ top: 0, left: 0, width: 250, maxHeight: 265 });

  const triggerRef = useRef<HTMLButtonElement>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const positionMenu = () => {

    const rect = triggerRef.current?.getBoundingClientRect();

    if (!rect) return;

    const viewportWidth = document.documentElement.clientWidth;

    const viewportHeight = window.innerHeight;

    const width = Math.max(80, Math.min(rect.width, viewportWidth - 16));

    const left = Math.max(8, Math.min(rect.left, viewportWidth - width - 8));

    const wanted = Math.min(265, question.options.length * 44 + 20);

    const below = Math.max(0, viewportHeight - rect.bottom - 8);

    const above = Math.max(0, rect.top - 8);

    const up = below < Math.min(wanted, 160) && above > below;

    const available = up ? above : below;

    const maxHeight = Math.min(wanted, Math.max(65, available));

    const top = up ? Math.max(8, rect.top - maxHeight) : Math.max(8, Math.min(rect.bottom, viewportHeight - maxHeight - 8));

    setPosition({ top, left, width, maxHeight });

  };

  useEffect(() => { setOpen(false); }, [question.id, termIndex]);

  useEffect(() => {

    if (!open) return;

    const outside = (event: PointerEvent) => {

      const target = event.target as Node;

      if (!triggerRef.current?.contains(target) && !menuRef.current?.contains(target)) setOpen(false);

    };

    const escape = (event: KeyboardEvent) => {

      if (event.key === "Escape") { setOpen(false); triggerRef.current?.focus(); }

    };

    const reposition = (event: Event) => {

      if (event.target instanceof Node && menuRef.current?.contains(event.target)) return;

      positionMenu();

    };

    document.addEventListener("pointerdown", outside);

    document.addEventListener("keydown", escape);

    window.addEventListener("scroll", reposition, true);

    window.addEventListener("resize", reposition);

    return () => {

      document.removeEventListener("pointerdown", outside);

      document.removeEventListener("keydown", escape);

      window.removeEventListener("scroll", reposition, true);

      window.removeEventListener("resize", reposition);

    };

  }, [open, question.options.length, selected]);

  const selectedText = selected >= 0 ? question.options[selected]?.text : undefined;

  return <div className={`viewerMatchPicker ${open ? "is-open" : ""} ${selectedText ? "has-value" : ""}`}>

    <button type="button" ref={triggerRef} className="viewerMatchTrigger" aria-label={`Description for ${question.terms[termIndex].label}`}

      aria-haspopup="listbox" aria-expanded={open} disabled={disabled}

      onClick={() => { if (open) { setOpen(false); return; } positionMenu(); setOpen(true); }}>

      <span>{selectedText || "Choose..."}</span>

      {selectedText

        ? <Icon name="tick.svg" size={20} />

        : <Icon name="arrow-down.svg" size={20} />}

    </button>

    {open && typeof document !== "undefined" && createPortal(

      <div ref={menuRef} className="viewerMatchPortal" role="listbox"

        aria-label={`Descriptions for ${question.terms[termIndex].label}`}

        style={{ position: "fixed", top: position.top, left: position.left, width: position.width,

          maxHeight: position.maxHeight, zIndex: 2147483000, display: "block", visibility: "visible",

          background: "#DFE6E9", boxShadow: "-4px -4px 4px #FFFFFF,4px 4px 4px #C4C4C4",

          overflowY: "auto", pointerEvents: "auto" }}>

        {question.options.map((option, optionIndex) => {

          const usedInAnother = answers.some((value, row) => row !== termIndex && value === optionIndex);

          const isSelected = optionIndex === selected;

          return <button key={`${option.id}-${optionIndex}`} type="button" role="option" aria-selected={isSelected}

            aria-disabled={usedInAnother && !isSelected} disabled={usedInAnother && !isSelected}

            className={`viewerMatchOption ${isSelected ? "is-chosen" : ""}`}

            onClick={() => { onSelect(isSelected ? -1 : optionIndex); setOpen(false); }}>

            <span className={`viewerAnswerRadio ${isSelected ? "is-selected" : ""}`} aria-hidden="true" />

            <span>{option.text}</span>

            {usedInAnother && !isSelected && <small>Used</small>}

          </button>;

        })}

      </div>, document.body)}

  </div>;

}

function HotspotCanvas({ question, markers, disabled, onMark, onRemove }: {
  question: MatchQuestion;
  markers: PlacedMarker[];
  disabled: boolean;
  onMark: (x: number, y: number) => void;
  onRemove: (id: string) => void;
}) {
  const hotspot = question.hotspot;
  // The known CPU sample stays visible even if an older draft points to a missing file.
  // Any actual creator image still takes priority as long as it loads successfully.
  const isCpuExample = question.id.startsWith("cpu-hotspot-demo") ||
    /click the part of the cpu that does calculations/i.test(question.text);
  const imageSrc = hotspot?.imageSrc || (isCpuExample ? CPU_DEMO_IMAGE_FALLBACK : "");
  const canvasRef = useRef<HTMLDivElement>(null);
  const imageRef = useRef<HTMLImageElement>(null);
  const [imageError, setImageError] = useState(false);
  const [displayImageSrc, setDisplayImageSrc] = useState(imageSrc);
  // These percentages describe the visible image INSIDE the unchanged default frame.
  // Markers must follow the image when its aspect ratio differs from the frame.
  const [imageBox, setImageBox] = useState({ left: 0, top: 0, width: 100, height: 100 });
  const [canvasSize, setCanvasSize] = useState({ width: 660, height: 383 });
  useEffect(() => { setImageError(false); setDisplayImageSrc(imageSrc); }, [imageSrc]);
  const handleImageError = () => {
    // Fallback covers older demo drafts that still reference the public PNG.
    if (isCpuExample && displayImageSrc !== CPU_DEMO_IMAGE_FALLBACK) {
      setDisplayImageSrc(CPU_DEMO_IMAGE_FALLBACK);
    } else {
      setImageError(true);
    }
  };
  // Measure the VISIBLE image within the Figma inset frame. This keeps markers
  // aligned when the creator uploads a wide, tall, or square picture.
  const measureImageBox = () => {
    const canvas = canvasRef.current;
    const image = imageRef.current;
    if (!canvas || !image || !image.naturalWidth || !image.naturalHeight) return;
    const outer = canvas.getBoundingClientRect();
    const frame = image.getBoundingClientRect();
    if (!outer.width || !outer.height || !frame.width || !frame.height) return;
    setCanvasSize(previous => previous.width === outer.width && previous.height === outer.height ? previous : { width: outer.width, height: outer.height });
    const scale = Math.min(frame.width / image.naturalWidth, frame.height / image.naturalHeight);
    const shownW = image.naturalWidth * scale;
    const shownH = image.naturalHeight * scale;
    const left = frame.left - outer.left + (frame.width - shownW) / 2;
    const top = frame.top - outer.top + (frame.height - shownH) / 2;
    setImageBox({
      left: left / outer.width * 100,
      top: top / outer.height * 100,
      width: shownW / outer.width * 100,
      height: shownH / outer.height * 100,
    });
  };
  useEffect(() => {
    const canvas = canvasRef.current;
    const image = imageRef.current;
    if (!canvas || !image) return;
    measureImageBox();
    const observer = typeof ResizeObserver !== "undefined" ? new ResizeObserver(measureImageBox) : null;
    observer?.observe(canvas);
    observer?.observe(image);
    window.addEventListener("resize", measureImageBox);
    return () => { observer?.disconnect(); window.removeEventListener("resize", measureImageBox); };
  }, [imageSrc]);
  if (!hotspot) return null;
  const handleClick = (event: ReactMouseEvent<HTMLDivElement>) => {
    if (disabled || !imageSrc || imageError) return;
    const bounds = event.currentTarget.getBoundingClientRect();
    if (!bounds.width || !bounds.height) return;
    const localX = (event.clientX - bounds.left) / bounds.width * 100;
    const localY = (event.clientY - bounds.top) / bounds.height * 100;
    const x = (localX - imageBox.left) / imageBox.width * 100;
    const y = (localY - imageBox.top) / imageBox.height * 100;
    if (x < 0 || x > 100 || y < 0 || y > 100) return; // Ignore letterboxed margins.
    onMark(x, y);
  };
  return <div className="viewerHotspotArea" aria-label="Clickable hotspot image">
    <p className="viewerHotspotInstructions">Click once on the image to place your marker. Click a marker to remove it. Markers: {hotspot.maxMarkers}</p>
    <div className="viewerHotspotFrame">
      <div ref={canvasRef} className="viewerHotspotCanvas" onClick={handleClick} role="group" aria-label="Select a point on the image">
        {imageSrc && !imageError ?
          <img ref={imageRef} className="viewerHotspotImage" src={displayImageSrc} alt={question.text} draggable={false}
            onLoad={measureImageBox}
            onError={handleImageError} />
          : <div className="viewerHotspotEmpty" role="status">
              {imageError ? "The saved image could not be loaded. Check the image path in the creator." : "No image saved yet. Upload an image in the creator to display it here."}
            </div>}
        {!imageError && imageSrc && markers.map(marker => {
          // Highlight the creator-defined region itself — never show a detached
          // label or a line over the diagram. The demo ALU is one such region.
          const region = hotspot.areas.find(area => area.id === marker.areaId);
          const imageWidthPx = Math.max(1, canvasSize.width * imageBox.width / 100);
          const imageHeightPx = Math.max(1, canvasSize.height * imageBox.height / 100);
          // Unknown/custom points still get a small target highlight, not a
          // floating answer card. Region bounds take priority when supplied.
          const width = region?.width && region.width > 0
            ? Math.min(100, region.width) : Math.min(100, 40 / imageWidthPx * 100);
          const height = region?.height && region.height > 0
            ? Math.min(100, region.height) : Math.min(100, 34 / imageHeightPx * 100);
          const x = Math.max(0, Math.min(100 - width, region?.width && region.width > 0
            ? region.x : marker.x - width / 2));
          const y = Math.max(0, Math.min(100 - height, region?.height && region.height > 0
            ? region.y : marker.y - height / 2));
          return <button type="button" key={marker.id}
            className="viewerHotspotRegionSelection"
            style={{
              left: `${imageBox.left + imageBox.width * x / 100}%`,
              top: `${imageBox.top + imageBox.height * y / 100}%`,
              width: `${imageBox.width * width / 100}%`,
              height: `${imageBox.height * height / 100}%`,
            }}
            aria-label={`Remove selected hotspot: ${marker.label}`}
            title={`${marker.label} — click to remove`}
            disabled={disabled}
            onClick={event => { event.stopPropagation(); onRemove(marker.id); }}>
            <span className="viewerHotspotRegionTarget" aria-hidden="true">
              <img src="/assets/assessmenticons/hotspot-target.svg" width={20} height={20} alt=""
                onError={event => { event.currentTarget.style.display = "none"; }} />
            </span>
          </button>;
        })}
      </div>
    </div>
  </div>;
}

function saveHotspotResult(draft:ViewerDraft, answers:Record<number,PlacedMarker[]>, flagged:number[], remainingSeconds:number, retry:boolean) {
  const original = (()=>{try{return JSON.parse(assessmentStorage.getItem("viewerAssessmentResult")||"{}");}catch{return {};}})();
  const questions = draft.questions.map((q,i)=>{
    const placed = answers[i] ?? [];
    const regions = q.hotspot?.areas ?? [];
    const correctTotal = regions.filter(area=>area.correct).length;
    const correct = placed.filter(marker=>regions.some(area=>area.id===marker.areaId && area.correct)).length;
    const answered = placed.length > 0;
    const fullyCorrect = answered && placed.length >= (q.hotspot?.maxMarkers ?? 1) && correct === placed.length;
    const earnedMarks = answered ? q.points * correct / Math.max(1,q.hotspot?.maxMarkers ?? 1) : 0;
    return {id:q.id,text:q.text,options:regions.map(area=>area.label), correct:0,
      selected:answered?(fullyCorrect?0:1):null, points:q.points,
      gradingStatus:!answered?"unanswered":fullyCorrect?"correct":"incorrect",
      earnedMarks:Math.min(q.points,earnedMarks),flagged:flagged.includes(i),bloom:q.bloom,hint:q.hint,
      hotspotAnswers:placed,expectedCorrectRegions:correctTotal};
  });
  const totalMarks=questions.reduce((n,q)=>n+q.points,0);
  const earnedMarks=questions.reduce((n,q)=>n+q.earnedMarks,0);
  const result={attemptId:typeof crypto!=="undefined"&&crypto.randomUUID?crypto.randomUUID():String(Date.now()),
    title:draft.title, assessmentType:"clickable-hotspot", questions,totalQuestions:questions.length,
    correctAnswers:questions.filter(q=>q.gradingStatus==="correct").length,
    incorrectAnswers:questions.filter(q=>q.gradingStatus==="incorrect").length,
    unanswered:questions.filter(q=>q.gradingStatus==="unanswered").length,
    totalMarks, earnedMarks,scorePercent:totalMarks?Math.round(earnedMarks/totalMarks*100):0,
    totalSeconds:draft.durationSeconds,usedSeconds:Math.max(0,draft.durationSeconds-remainingSeconds),
    flaggedQuestionIndexes:flagged,submittedAt:new Date().toISOString(),
    retryAttemptsUsed:retry?Number(original.retryAttemptsUsed||2):1,
    retryAttemptsAllowed:Number(original.retryAttemptsAllowed||2),
    retryDurationMinutes:Number(original.retryDurationMinutes||15)};
  assessmentStorage.setItem(retry?"viewerRetryResult":"viewerAssessmentResult",JSON.stringify(result));
  if(!retry){
    let prior:unknown=[];
    try{prior=JSON.parse(assessmentStorage.getItem("viewerAttempts")||"[]");}catch{prior=[];}
    assessmentStorage.setItem("viewerAttempts",JSON.stringify([...(Array.isArray(prior)?prior:[]),result]));
    assessmentStorage.setItem("viewerAttemptDraft",JSON.stringify({finished:true}));
    const id=getActiveAssessmentId();const existing=id?getAssessment(id):undefined;
    if(existing)updateAssessment({attemptCount:(existing.attemptCount||0)+1});
  }
  return result;
}

export default function ClickableHotspotViewerPage() {

  const router = useRouter();

  const [draft, setDraft] = useState<ViewerDraft>(HOTSPOT_DEMO);

  const [current, setCurrent] = useState(0);

  const [answers, setAnswers] = useState<Record<number, number[]>>({});
  const [hotspotAnswers, setHotspotAnswers] = useState<Record<number, PlacedMarker[]>>({});

  const [flagged, setFlagged] = useState<number[]>([]);

  const [skipped, setSkipped] = useState<number[]>([]);

  const [hintOpen, setHintOpen] = useState(true);

  const [expiresAt, setExpiresAt] = useState(0);

  const [now, setNow] = useState(0);

  const [submitted, setSubmitted] = useState(false);

  const [ready, setReady] = useState(false);

  const [notice, setNotice] = useState("");
const [submitOpen,setSubmitOpen]=useState(false);
const [successOpen,setSuccessOpen]=useState(false);
const [releasePolicy,setReleasePolicy]=useState<ReturnType<typeof releaseForAssessment>|null>(null);
const retry=typeof window!=="undefined" && new URLSearchParams(window.location.search).get("retry")==="wrong";

  // Demo and real learner attempts must never share a session record.
  const isDemoPreview = typeof window !== "undefined" &&
    new URLSearchParams(window.location.search).has("demo");
  const viewerSessionKey = isDemoPreview ? `${SESSION_KEY}:demo` : SESSION_KEY;

  const signature = `${draft.title}|${draft.questions.length}|${draft.questions.map(q => q.id + q.text + (q.hotspot?.imageSrc ? q.hotspot.imageSrc.length + q.hotspot.imageSrc.slice(-48) : "")).join("|")}`;

  useEffect(() => {

    if (!isDemoPreview && !retry) {
  try {
    const attempt = JSON.parse(assessmentStorage.getItem("viewerAttemptDraft")||"{}");
    if (attempt.finished) {router.replace("/learner");return;}
  } catch { /* Ignore invalid legacy attempt state. */ }
}
const loaded = loadViewerDraft();

    const stamp = `${loaded.title}|${loaded.questions.length}|${loaded.questions.map(q => q.id + q.text + (q.hotspot?.imageSrc ? q.hotspot.imageSrc.length + q.hotspot.imageSrc.slice(-48) : "")).join("|")}`;

    const time = Date.now();

    setDraft(loaded);

    setNow(time);

    let state: Partial<ViewerState> = {};

    try { state = JSON.parse(assessmentStorage.getItem(viewerSessionKey) || "{}"); }

    catch { /* Start a fresh attempt. */ }

    const resetDemo = new URLSearchParams(window.location.search).get("reset") === "1" && isDemoPreview;
    if (!resetDemo && state.signature === stamp && !state.submitted && Number(state.expiresAt) > time) {

      setCurrent(Math.min(Math.max(Number(state.current) || 0, 0), loaded.questions.length - 1));

      setAnswers(state.answers ?? {});
      setHotspotAnswers(state.hotspotAnswers ?? {});

      setFlagged(Array.isArray(state.flagged) ? state.flagged : []);

      setSkipped(Array.isArray(state.skipped) ? state.skipped : []);

      setExpiresAt(state.expiresAt || time + loaded.durationSeconds * 1000);

      setSubmitted(Boolean(state.submitted));

    } else {

      setCurrent(0);

      setAnswers({});
      // Optional selection example: ?demo=hotspot&reset=1&example=alu
      // Normal creator questions and unselected demo flows are unchanged.
      const showAluExample = isDemoPreview && new URLSearchParams(window.location.search).get("example") === "alu" &&
        loaded.questions[0]?.hotspot?.areas.some(area => area.id === "alu");
      setHotspotAnswers(showAluExample ? {0: [{id:"demo-alu",x:57,y:48,areaId:"alu",label:"ALU"}]} : {});

      setFlagged([]);

      setSkipped([]);

      setSubmitted(false);

      setExpiresAt(time + loaded.durationSeconds * 1000);

    }

    setReady(true);

  }, []);

  useEffect(() => {

    if (!ready || submitted) return;

    const timer = window.setInterval(() => setNow(Date.now()), 1000);

    return () => window.clearInterval(timer);

  }, [ready, submitted]);

  const questions = draft.questions;

  const question = questions[current];

  const total = questions.length;

  const isAnswered = (q: MatchQuestion, i: number) => q.hotspot
    ? (hotspotAnswers[i]?.length ?? 0) >= q.hotspot.maxMarkers
    : complete(q, answers[i]);
  const isPartial = (q: MatchQuestion, i: number) => q.hotspot
    ? (hotspotAnswers[i]?.length ?? 0) > 0 && !isAnswered(q, i)
    : partial(q, answers[i]);
  const answered = questions.filter(isAnswered).length;

  const remaining = Math.max(0, total - answered);

  const progress = total ? Math.round(answered / total * 100) : 0;

  const secondsLeft = expiresAt ? Math.max(0, Math.ceil((expiresAt - now) / 1000)) : draft.durationSeconds;

  const score = useMemo(() => questions.reduce((sum, q, i) => {

    if (q.hotspot) {
      const placed = hotspotAnswers[i] ?? [];
      if (placed.length < q.hotspot.maxMarkers) return sum;
      const areas = q.hotspot.areas;
      if (!areas.length) return sum + q.points;
      const anyCorrectDefined = areas.some(area => area.correct);
      const correctPlaced = placed.filter(marker => areas.some(area => area.id === marker.areaId &&
        (!anyCorrectDefined || area.correct))).length;
      return sum + q.points * Math.min(correctPlaced, q.hotspot.maxMarkers) / q.hotspot.maxMarkers;
    }
    if (!complete(q, answers[i])) return sum;

    const correctCount = q.terms.filter((_, row) => answers[i]?.[row] === q.correct[row] && q.correct[row] !== -1).length;

    return sum + (q.points * correctCount / Math.max(1, q.terms.length));

  }, 0), [questions, answers, hotspotAnswers]);

  useEffect(() => {

    if (!ready) return;

    const state: ViewerState = { signature, current, answers, hotspotAnswers, flagged, skipped, expiresAt, submitted };

    try { assessmentStorage.setItem(viewerSessionKey, JSON.stringify(state)); }

    catch { /* Continue when browser storage is unavailable. */ }

  }, [ready, signature, current, answers, hotspotAnswers, flagged, skipped, expiresAt, submitted]);

  useEffect(() => {
  if(!ready || submitted || !expiresAt || !draft.questions.length || secondsLeft > 0) return;
  try {
    saveHotspotResult(draft,hotspotAnswers,flagged,0,retry);
    setSubmitted(true);
    setNotice("Time is up. Your assessment has been submitted.");
    setReleasePolicy(releaseForAssessment("clickable-hotspot"));
    setSuccessOpen(true);
  } catch { setNotice("Your result could not be saved. Please contact your instructor."); }
}, [ready,submitted,expiresAt,secondsLeft,draft,hotspotAnswers,flagged,retry]);

const selectMatch = (row: number, option: number) => {

    if (submitted || !question) return;

    setAnswers(previous => {

      const next = Array.from({ length: question.terms.length }, (_, i) => previous[current]?.[i] ?? -1);

      // One description can be matched to one term; changing a match frees the old row.

      if (option >= 0) next.forEach((value, i) => { if (i !== row && value === option) next[i] = -1; });

      next[row] = option;

      return { ...previous, [current]: next };

    });

    setSkipped(previous => previous.filter(i => i !== current));

    setNotice("");

  };

  const placeHotspotMarker = (x: number, y: number) => {
    if (!question?.hotspot || submitted) return;
    const hotspot = question.hotspot;
    const area = hotspot.areas.find(item => x >= item.x && x <= item.x + item.width &&
      y >= item.y && y <= item.y + item.height);
    const marker: PlacedMarker = {
      id: `${Date.now()}-${Math.random().toString(36).slice(2)}`,
      x, y, areaId: area?.id, label: area?.label ?? "Selected spot",
    };
    setHotspotAnswers(previous => {
      const prior = previous[current] ?? [];
      const next = prior.length >= hotspot.maxMarkers ?
        (hotspot.maxMarkers === 1 ? [marker] : [...prior.slice(0, -1), marker]) :
        [...prior, marker];
      return { ...previous, [current]: next };
    });
    setSkipped(previous => previous.filter(i => i !== current));
    setNotice("");
  };
  const removeHotspotMarker = (markerId: string) => {
    if (submitted) return;
    setHotspotAnswers(previous => ({
      ...previous, [current]: (previous[current] ?? []).filter(marker => marker.id !== markerId),
    }));
  };

  const goTo = (index: number) => {

    if (submitted || index < 0 || index >= total || index === current) return;

    if (question && !isAnswered(question, current)) {

      setSkipped(previous => previous.includes(current) ? previous : [...previous, current]);

    }

    setCurrent(index);

    setHintOpen(true);

    setNotice("");

  };

  const toggleFlag = () => {

    if (submitted) return;

    setFlagged(previous => previous.includes(current)

      ? previous.filter(i => i !== current) : [...previous, current]);

  };

  const submit = () => {
  if(submitted || !total) return;
  if(remaining>0){setNotice("Answer every question before submitting the assessment.");return;}
  setSubmitOpen(true);
};
const confirmSubmit = () => {
  if(submitted)return;
  try {
    saveHotspotResult(draft,hotspotAnswers,flagged,secondsLeft,retry);
    setSubmitOpen(false);
    setSubmitted(true);
    setReleasePolicy(releaseForAssessment("clickable-hotspot"));
    setSuccessOpen(true);
    setNotice("");
  } catch {setSubmitOpen(false);setNotice("Unable to save the assessment result. Please try again.");}
};
const viewerBase=`/assessments/${encodeURIComponent(getActiveAssessmentId()||"")}/viewer`;

return <main className="superAdminPage institutionAdminPage viewerAppShell viewMatchFollowingApp">

    <div className="dashboardLayout viewerLayout">

      <Sidebar />

      <section className="mainContent viewerMain">

        <div className="viewerSharedHeader"><Header /></div>

        <div className="institutionScrollArea viewerScroll">

          <div className="pageContent institutionPageContent viewerContent">

            <div className="viewerExamTop">

              <nav className="viewerBreadcrumb" aria-label="Breadcrumb">

                <Link href="/learner">Dashboard</Link><Icon name="arrow-right-double.svg" size={20} />

                <Link href="/learner">Assessment</Link><Icon name="arrow-right-double.svg" size={20} />

                <strong>{draft.title}</strong>

              </nav>

              <Stopwatch seconds={secondsLeft} />

            </div>

            <div className="viewerPageHeading viewerExamHeading"><h1>{draft.title}</h1></div>

            <div className="viewerExamGrid">

              <section className="viewerExamCard viewerQuestionCard" aria-label="Assessment question">

                <div className="viewerProgressArea">

                  <div className="viewerProgressLabel">

                    <strong>{total ? current + 1 : 0}<span>/{total}</span></strong>

                    <strong className="viewerMarks">{question?.points ?? 0} Marks</strong>

                  </div>

                  <div className="viewerProgressRow">

                    <div className="viewerProgressTrack"><span style={{ width: `${progress}%` }} /></div>

                    <strong>{progress}%</strong>

                  </div>

                </div>

                {question ? <>

                  <div className="viewerQuestionHeading">

                    <h2>Question {current + 1}</h2>

                    <p>{question.text}</p>

                  </div>

                  {question.hotspot ?
                    <HotspotCanvas key={question.id} question={question}
                      markers={hotspotAnswers[current] ?? []} disabled={submitted}
                      onMark={placeHotspotMarker} onRemove={removeHotspotMarker} />
                    : <div className="viewerMatching" aria-label="Match the following">

                    <div className="viewerMatchingHeading"><strong>{question.columnA || "Term"}</strong><strong>{question.columnB || "Description"}</strong></div>

                    {question.terms.map((term, index) => <div className="viewerMatchRow" key={`${current}-${term.id}-${index}`}>

                      <div className="viewerMatchTerm">

                        {String.fromCharCode(65 + index)}. {term.label}

                      </div>

                      <MatchSelect question={question} termIndex={index}

                        selected={answers[current]?.[index] ?? -1}

                        answers={answers[current] ?? []} disabled={submitted}

                        onSelect={option => selectMatch(index, option)} />

                    </div>)}

                  </div>}

                  {question.allowHint && (question.hint || question.hotspot) && <section className="viewerHintBox">

                    <button type="button" className="viewerHintToggle" aria-expanded={hintOpen}

                      onClick={() => setHintOpen(value => !value)}>

                      <span className="viewerHintTitle">

                        <span className="viewerHintIcon"><Icon name="idea.svg" size={25} /></span>

                        <span>Hint{hintOpen && <small>{question.hint || "Click the image where the requested part is located."}</small>}</span>

                      </span>

                      <span className="viewerHintEye"><Icon name={hintOpen ? "view.svg" : "eye-off.svg"} size={20} /></span>

                    </button>

                  </section>}

                  <div className="viewerQuestionSettings">

                    <div><label>Bloom’s Taxonomy</label><span className="viewerBloomValue">{question.bloom || "Not specified"}</span></div>

                    <button type="button" className={`viewerFlagButton ${flagged.includes(current) ? "isFlagged" : ""}`}

                      disabled={submitted} onClick={toggleFlag}>

                      <Icon name="flag.svg" size={22} />{flagged.includes(current) ? "Remove flag" : "Flag for review"}

                    </button>

                  </div>

                  {notice && <p className="viewerInlineNotice" role="status">{notice}</p>}

                  <div className="viewerExamActions">

                    <button type="button" className="viewerExamButton" disabled={current === 0}

                      onClick={() => goTo(current - 1)}><Icon name="arrowleft.svg" />Previous</button>

                    <button type="button" className="viewerExamButton viewerNext"

                      disabled={submitted && current === total - 1}

                      onClick={() => current === total - 1 ? submit() : goTo(current + 1)}>

                      {current === total - 1 ? (submitted ? "Submitted" : "Submit") : "Next"}<Icon name="arrowrightg.svg" />

                    </button>

                  </div>

                </> : <p className="viewerInlineNotice">No matching questions were found in this assessment.</p>}

              </section>

              <aside className="viewerExamCard viewerNavigator">

                <h2>Question Navigator</h2>

                <div className="viewerQuestionTiles" aria-label="Choose question">

                  {questions.map((q, index) => {

                    const state = index === current ? "current"

                      : flagged.includes(index) ? "flagged"

                      : isAnswered(q, index) ? "answered"

                      : isPartial(q, index) || skipped.includes(index) ? "skipped" : "remaining";

                    return <button type="button" key={q.id + index}

                      className={`viewerQuestionTile is-${state}`}

                      aria-label={`Question ${index + 1}${flagged.includes(index) ? ", flagged" : ""}`}

                      aria-current={index === current ? "step" : undefined}

                      onClick={() => goTo(index)}>{index + 1}</button>;

                  })}

                </div>

                <div className="viewerStatusRows">

                  <div><Icon name="checkmark-circle.svg" /><span>Answered</span><strong>{String(answered).padStart(2, "0")}</strong></div>

                  <div><span className="viewerRemainingCircle" /><span>Remaining</span><strong>{String(remaining).padStart(2, "0")}</strong></div>

                  <div><Icon name="flag.svg" /><span>Flagged</span><strong>{String(flagged.length).padStart(2, "0")}</strong></div>

                </div>

                <h2 className="viewerToolsHeading">Tools</h2>

                <div className="viewerToolsList">

                  <button type="button" onClick={() => router.push(`${viewerBase}/scratch`)}><Icon name="sticky-note.svg" />Scratch Pad<Icon name="arrowupright.svg" size={18} /></button>

                  <button type="button" onClick={() => router.push(`${viewerBase}/calculator`)}><Icon name="calculator.svg" />Calculator<Icon name="arrowup.svg" size={18} /></button>

                  <button type="button" onClick={() => router.push(`${viewerBase}/formulasheet`)}><Icon name="sigma.svg" />Formula Sheet<Icon name="arrowupg.svg" size={18} /></button>

                </div>

              </aside>

            </div>

          </div>

        </div>

      </section>

    </div>

  {submitOpen && !submitted && <ViewerSubmitConfirm answered={answered} remaining={remaining} flagged={flagged.length} onBack={()=>setSubmitOpen(false)} onSubmit={confirmSubmit}/>}
{successOpen && releasePolicy && <TextSubmitSuccess title={draft.title} scorePercent={total?Math.round(score/Math.max(1,questions.reduce((sum,q)=>sum+q.points,0))*100):0} pendingCount={0} passingScore="60%" release={releasePolicy} isRetry={retry} onClose={()=>{setSuccessOpen(false);router.push(resultPath());}}/>}
</main>;

}
